const $=id=>document.getElementById(id);
const sigils=['ᛠ','ᛑ','ᚹ','ᛟ','ᛉ','ᛞ','ᚦ','ᛇ','ᚨ','ᛗ','ᛚ','ᚱ','ᛃ','ᛏ','ᚷ','ᛖ','ᚾ','ᛜ','ᛒ','ᚺ','ᛋ','ᛁ','ᚢ','ᚠ'];
const names=['潮生','余响','行旅','归藏','庇护','昼夜','棘门','界木','言灵','同生','流转','归途','丰年','指引','馈赠','双影','余烬','种子','新生','寒息','日轮','静止','原力','财富'];
const descriptions=['万物自潮水而来。','声音散去，记忆仍在。','无名者走过无名之地。','将不愿遗忘之物收起。','为远行者留一盏灯。','光与影在此交替。','越过荆棘，方能相见。','根须连接两个世界。','被说出的名字有了重量。','彼此成为存在的证据。','潮水从不沿原路归来。','每条路都记得足迹。','等待也会结出果实。','向着最后一颗星。','给予之物终将回响。','另一个自己藏在水面。','熄灭之后，尚有温度。','未曾发生之事在此沉睡。','破土时请保持安静。','雾中传来冬天的呼吸。','白昼的碎片。','让这一瞬停留片刻。','石头记得山的名字。','所拥有的，皆为暂借。'];
let closed=false,chapter=0,sound=false,audio,drag=null,rx=9,ry=-7,rz=-5;
function tone(freq=300){if(!sound)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,audio.currentTime+.3);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.5);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.5)}
sigils.forEach((s,i)=>{const b=document.createElement('button');b.className='rune'+(i===0?' active':'')+(i>17?' dark':'');b.textContent=s;b.setAttribute('aria-label',names[i]);b.setAttribute('aria-pressed',String(i===0));b.onclick=()=>{document.querySelectorAll('.rune').forEach(r=>{r.classList.remove('active');r.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');$('runeName').textContent=names[i];$('runeText').textContent=descriptions[i];$('runeCount').textContent=String(i+1).padStart(2,'0')+' / 24';tone(220+i*17)};$('runes').append(b)});
function toggle(){closed=!closed;document.body.classList.toggle('closed',closed);$('toggle').innerHTML=closed?'<span>◇</span> 开启手记':'<span>✕</span> 合上手记';$('toggle').setAttribute('aria-expanded',String(!closed));$('runePanel').inert=closed;$('prev').disabled=closed;$('next').disabled=closed;tone(closed?160:280)}
$('toggle').onclick=toggle;$('bookmark').onclick=toggle;$('toggle').setAttribute('aria-expanded','true');
const chapters=[['潮间之物','潮汐中的旅人','它们在退潮时现身，循着记忆的纹路行走。','不要询问姓名，只需为它们留一盏灯。','余响之瓶','VESSEL OF ECHOES','封存离去者最后一句话。','月落以后，瓶中会泛起潮声。','渡鸦行箱','THE RAVEN’S COFFER','灰潮渡口','第七个无月夜'],['雾港遗存','守灯人的契约','雾气吞没航道时，守灯人便会醒来。','灯火每明灭一次，就有一艘船归港。','雾灯之钥','KEY OF THE MIST','钥匙没有齿，只有一道刻痕。','握紧它，便能听见远方的钟声。','漂流密匣','DRIFTWOOD RELIQUARY','雾港旧灯塔','第三次雾钟响起'],['无月之境','昨日的回声','它们没有影子，脚下却总有两行足迹。','一行通向昨日，另一行尚未写成。','遗忘之露','DEW OF OBLIVION','收集自无人记得的清晨。','每一滴，都藏着一个未完的梦。','夜航者之箱','THE NIGHTFARER’S CHEST','静默海岸','最后一颗星沉没']];
function turn(delta){if(closed)return;chapter=(chapter+delta+3)%3;const c=chapters[chapter];$('chapterTitle').textContent=c[1];$('chapterText').replaceChildren(document.createTextNode(c[2]),document.createElement('br'),document.createTextNode(c[3]));$('itemTitle').textContent=c[4];$('itemSubtitle').textContent=c[5];$('itemText').replaceChildren(document.createTextNode(c[6]),document.createElement('br'),document.createTextNode(c[7]));$('chestTitle').textContent=c[8];$('chestSubtitle').textContent=c[9];$('chapterIndicator').innerHTML=c[0]+' <small>0'+(chapter+1)+' — 03</small>';document.querySelector('.left-page .page-top span').textContent=['第一章','第二章','第三章'][chapter]+' / '+c[0];document.querySelector('.right-page footer span').textContent='采集地 · '+c[10];document.querySelector('.left-page footer span').textContent='观察记录 · '+c[11];document.querySelector('.left-page .page-number').textContent=String(chapter*2+1).padStart(2,'0');document.querySelector('.right-page .page-number').textContent=String(chapter*2+2).padStart(2,'0');document.querySelector('.art-bottle').style.backgroundPosition=chapter===1?'0% 100%':'100% 0%';document.querySelectorAll('.page').forEach(p=>{p.classList.remove('changing');void p.offsetWidth;p.classList.add('changing')});tone(350)}
$('prev').onclick=()=>turn(-1);$('next').onclick=()=>turn(1);$('sound').onclick=()=>{sound=!sound;$('sound').textContent='声音 · '+(sound?'开':'关');$('sound').setAttribute('aria-pressed',String(sound));tone()};
function pose(){ $('book').style.transform=`rotateX(${rx}deg) rotateY(${ry}deg) rotateZ(${rz}deg)` }
$('bookWrap').onpointerdown=e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,rx,ry};$('bookWrap').setPointerCapture(e.pointerId)};
$('bookWrap').onpointermove=e=>{if(!drag)return;ry=Math.max(-30,Math.min(30,drag.ry+(e.clientX-drag.x)*.12));rx=Math.max(-15,Math.min(30,drag.rx-(e.clientY-drag.y)*.1));pose()};
$('bookWrap').onpointerup=()=>drag=null;$('bookWrap').onpointercancel=()=>drag=null;$('reset').onclick=()=>{rx=9;ry=-7;rz=-5;pose()};
document.addEventListener('keydown',e=>{if(e.target.closest('button,a,input')||e.repeat)return;if(e.code==='Space'){e.preventDefault();toggle()}if(e.key==='ArrowRight')turn(1);if(e.key==='ArrowLeft')turn(-1);if(e.key==='Escape'&&!closed)toggle()});
